def normalize_tags(tags):
    seen = set()
    result = []
    for tag in tags:
        key = tag.strip().casefold()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return result

def most_common_word(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return max(counts, key=counts.get)

def intersection_labels(first, second):
    second_labels = {label.casefold() for label in second}
    seen = set()

    for label in first:
        key = label.casefold()
        if key in second_labels and key not in seen:
            seen.add(key)
            yield label

def common_suffix(words):
    if not words:
        return ""

    suffix = []
    for characters in zip(*(word[::-1] for word in words)):
        if len(set(characters)) != 1:
            break
        suffix.append(characters[0])

    return "".join(reversed(suffix))

def parse_clock(text):
    import re

    match = re.fullmatch(r"\s*(\d{1,2}):(\d{2})\s*(AM|PM)\s*", text, re.IGNORECASE)
    if match is None:
        raise ValueError("Invalid clock value")

    hour, minute = int(match.group(1)), int(match.group(2))
    if not 1 <= hour <= 12 or not 0 <= minute <= 59:
        raise ValueError("Invalid clock value")

    hour %= 12
    if match.group(3).upper() == "PM":
        hour += 12
    return hour * 60 + minute

def sort_events(events):
    from datetime import datetime, timezone

    def parse_time(value):
        if value.endswith("Z"):
            value = value[:-1] + "+00:00"
        parsed = datetime.fromisoformat(value)
        if parsed.tzinfo is None:
            return parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)

    return sorted(events, key=lambda event: parse_time(event["time"]))

def matrix_multiply(left, right):
    return [
        [sum(a * b for a, b in zip(row, column)) for column in zip(*right)]
        for row in left
    ]

def count_islands(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()
    islands = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 1 or (r, c) in visited:
                continue

            islands += 1
            visited.add((r, c))
            stack = [(r, c)]

            while stack:
                row, col = stack.pop()
                for nr, nc in ((row - 1, col), (row + 1, col),
                               (row, col - 1), (row, col + 1)):
                    if (0 <= nr < rows and 0 <= nc < cols
                            and grid[nr][nc] == 1
                            and (nr, nc) not in visited):
                        visited.add((nr, nc))
                        stack.append((nr, nc))

    return islands
